import { Component, input, linkedSignal, output } from '@angular/core';

@Component({
  selector: 'app-rename-field',
  template: `
    <input #box [value]="draft()" (input)="draft.set(box.value)" />
    <button (click)="renamed.emit(draft())">Save</button>
  `,
})
export class RenameField {
  readonly name = input.required<string>();
  readonly renamed = output<string>();

  // Writable, and reset to the new name whenever the parent sends one
  readonly draft = linkedSignal(() => this.name());
}
